var d = msg.payload;
if (typeof d !== 'object' || d === null || typeof d.suhu !== 'number') {
  node.warn('Payload sensor tidak valid, diabaikan');
  return null;
}
d.received = new Date().toISOString();

// batas suhu (Tugas 1)
var thr = flow.get('threshold');
var max = (thr && typeof thr.max === 'number') ? thr.max : null;
d.over_threshold = (max !== null && d.suhu > max);

// cache data terakhir (history ada di SQLite - Tugas 5)
flow.set('lastSensor', d);

// output 1 -> SQLite
var ins = { params: {
  $suhu: d.suhu,
  $kelembaban: d.kelembaban,
  $ts: d.timestamp || null,
  $received: d.received
}};

// output 2 -> WebSocket (Tugas 4)
var wsMsg = { payload: { type: 'sensor', data: d } };

// output 3 -> notifikasi, hanya sekali setiap suhu menyeberang batas
var alertMsg = null;
var alerted = flow.get('alerted') || false;
if (d.over_threshold && !alerted) {
  flow.set('alerted', true);
  var a = { suhu: d.suhu, max: max, time: d.received,
            message: 'Suhu ' + d.suhu + ' C melewati batas ' + max + ' C' };
  flow.set('lastAlert', a);
  alertMsg = { payload: { type: 'alert', data: a } };
} else if (!d.over_threshold && alerted) {
  flow.set('alerted', false);
}
return [ins, wsMsg, alertMsg];

